// Renders docs/parity-checklist.md from the PRD features and the rows.
import 'parity_model.dart';

const checklistPath = '../docs/parity-checklist.md';
const prdPath = '../docs/02-prd.md';
const planPath = '../docs/09-implementation-plan.md';

const _intro = '''
<!-- GENERATED by app/tool/parity_checklist.dart from docs/02-prd.md and
     app/tool/parity/parity_rows*.dart. Do not edit by hand: change the rows
     and run `dart run tool/parity_checklist.dart` from app/. -->
# Platform parity checklist (R-13)

One row per v1 feature in `docs/02-prd.md` (its `[Fx.y]` ID) × iPhone, Android, macOS and web.
`test/policy/parity_checklist_test.dart` fails CI when a PRD ID has no row, a row has no PRD ID, a
cell has no evidence, a cited file is missing, a "later"/"gap" cell names no existing plan task, or
this file is stale. It is the 08 §6.2 release gate: every cell ✓ (or n/a, or an owner gate that is
ticked in 08 §6.1) before a tag.

| Status | Meaning |
|---|---|
| ✓ CI | Automated tests below cover it on this target (shared Dart code runs the same on all four; all four targets build in CI) |
| ✓ device | Also run on a simulator, emulator, the Mac or Chrome — the note says when |
| ◐ owner | Needs the owner: accounts, consoles or physical hardware (08 §6.1) |
| ◐ manual | Needs a person at the screen; a person check in 08 §6.1 E |
| → later | Not built yet by plan; the note names the task |
| — n/a | Not on this target by spec |
| ✗ gap | Missing with no recorded decision; the note names the plan task that closes it |
''';

/// The whole checklist document.
String renderChecklist(
  List<PrdFeature> features,
  Map<String, ParityRow> rows,
  List<Run> runs,
) {
  final b = StringBuffer(_intro)
    ..writeln()
    ..writeln('## Summary')
    ..writeln()
    ..writeln(_summary(features, rows))
    ..writeln();
  String? section;
  for (final f in features) {
    final row = rows[f.id];
    if (row == null) continue;
    if (f.section != section) {
      section = f.section;
      b
        ..writeln('## $section')
        ..writeln()
        ..writeln(
          '| ID | Feature | iPhone | Android | macOS | Web | Automated evidence |',
        )
        ..writeln('|---|---|---|---|---|---|---|');
    }
    b.writeln(_row(f, row));
  }
  b
    ..writeln()
    ..writeln('## Notes')
    ..writeln();
  for (final f in features) {
    final note = rows[f.id]?.note ?? '';
    if (note.isNotEmpty) b.writeln('- **${f.id}** $note');
  }
  b
    ..writeln()
    ..writeln('## Device and browser runs')
    ..writeln()
    ..writeln('| Date | Target | Run | Result |')
    ..writeln('|---|---|---|---|');
  for (final r in runs) {
    b.writeln('| ${r.date} | ${r.target.label} | ${r.what} | ${r.result} |');
  }
  return b.toString();
}

String _row(PrdFeature f, ParityRow row) {
  final cells = [for (final t in Target.values) _cell(row.cell(t))].join(' | ');
  final tests = row.tests.map((t) => '`$t`').join('<br>');
  return '| ${f.id} | ${f.summary} | $cells | $tests |';
}

String _cell(Cell c) =>
    c.note.isEmpty ? c.status.label : '${c.status.label}<br>${c.note}';

String _summary(List<PrdFeature> features, Map<String, ParityRow> rows) {
  final b = StringBuffer()
    ..writeln('${features.length} features × 4 targets.')
    ..writeln()
    ..writeln('| Status | ${Target.values.map((t) => t.label).join(' | ')} |')
    ..writeln('|---|---|---|---|---|');
  for (final s in Status.values) {
    final counts = [
      for (final t in Target.values)
        features.where((f) => rows[f.id]?.cell(t).status == s).length,
    ];
    b.writeln('| ${s.label} | ${counts.join(' | ')} |');
  }
  return b.toString().trimRight();
}
